//! Runtime class metadata — the `obj` equivalent of C++ RTTI.
//!
//! Every class generated by `#[obj::class]` emits one `&'static ClassMeta`, reachable from
//! any polymorphic handle through a single virtual call. Casts are resolved by looking the target
//! class up in [`ClassMeta::bases`].

use core::any::TypeId;
use core::fmt;

/// Uniquely identifies a class at runtime.
pub type ClassId = TypeId;

/// A type-erased pointer to a compiler-generated `dyn` vtable.
///
/// Used to rebuild a fat pointer when casting to a class whose interface is not a supertrait of
/// the one currently held (a *sidecast* across multiple inheritance).
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct VTablePtr(pub(crate) *const ());

// SAFETY: a vtable is a `'static`, read-only object emitted by the compiler. `VTablePtr` only ever
// reads it (and only as the metadata half of a fat pointer), so it is sound to share across
// threads.
unsafe impl Send for VTablePtr {}
// SAFETY: see the `Send` impl above.
unsafe impl Sync for VTablePtr {}

impl VTablePtr {
    /// Wraps a raw vtable pointer.
    ///
    /// # Safety
    ///
    /// `raw` must be the vtable half of a fat pointer produced by coercing some concrete type `C`
    /// to a `dyn` trait `D`. Pairing it with a data pointer that does not point at a live `C` is
    /// undefined behaviour.
    #[must_use]
    pub const unsafe fn from_raw(raw: *const ()) -> Self {
        Self(raw)
    }
}

impl fmt::Debug for VTablePtr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "VTablePtr({:p})", self.0)
    }
}

/// One entry of a class's base table.
///
/// A class's table lists the class itself followed by every one of its ancestors, so a single
/// lookup answers both "is this an `X`?" and "where is the `X` subobject?".
///
/// Class identity is stored as `fn() -> ClassId` rather than a plain [`ClassId`] because
/// `TypeId::of` only became callable in `const` contexts after this crate's MSRV.
#[derive(Clone, Copy, Debug)]
pub struct BaseEntry {
    /// The ancestor class this entry describes.
    pub id: fn() -> ClassId,
    /// Byte offset from the start of the most-derived object to this ancestor's *data* subobject.
    ///
    /// Only meaningful for the plain-data view (`&Base`). Polymorphic casts deliberately ignore
    /// it — see [`ClassMeta`].
    pub data_offset: usize,
    /// Vtable for *most-derived-as-this-ancestor's-interface*.
    ///
    /// `None` throughout the table of an **abstract** class: a class with a pure virtual method
    /// implements no interface, not even its own, so no such vtable exists. Because an abstract
    /// class can never be the most-derived class of a live object, these tables are never the ones
    /// consulted by a cast — the most-derived class's table is, and that one is always fully
    /// populated.
    pub dyn_vtable: Option<VTablePtr>,
}

/// Runtime description of a class.
///
/// # Why `data_offset` and `dyn_vtable` disagree
///
/// Rust implements a `dyn` trait for the *most-derived* type, so the data half of a polymorphic
/// fat pointer always addresses the start of the complete object, whatever interface it is viewed
/// through. Only the plain-data view of a secondary base needs the byte offset applied.
///
/// Applying `data_offset` when rebuilding a polymorphic pointer is therefore a bug, and one that
/// fails *silently* by dispatching to the base class's own implementation instead of the
/// override.
#[derive(Debug)]
pub struct ClassMeta {
    /// The class's name, as written in the source.
    pub name: &'static str,
    /// This class's own identifier.
    pub id: fn() -> ClassId,
    /// This class followed by all of its ancestors, most-derived first.
    pub bases: &'static [BaseEntry],
}

impl ClassMeta {
    /// This class's identifier.
    ///
    /// Named `class_id` rather than `id` so it cannot be confused with the `id` field, which is a
    /// function pointer.
    #[must_use]
    pub fn class_id(&self) -> ClassId {
        (self.id)()
    }

    /// Looks up `target` in this class's base table.
    #[must_use]
    pub fn find_base(&self, target: ClassId) -> Option<&'static BaseEntry> {
        // Hierarchies are short in practice, so a linear scan beats anything with setup cost.
        self.bases.iter().find(|b| (b.id)() == target)
    }

    /// Returns whether this class is, or derives from, `target`.
    #[must_use]
    pub fn is_a(&self, target: ClassId) -> bool {
        self.find_base(target).is_some()
    }
}

/// Placeholder class used to fill unused [`BaseTable`] slots. Never matches a real class.
struct Nobody;

impl BaseEntry {
    /// An entry that matches nothing, used to pad a [`BaseTable`].
    pub const EMPTY: BaseEntry = BaseEntry {
        id: TypeId::of::<Nobody>,
        data_offset: 0,
        dyn_vtable: None,
    };
}

/// Maximum number of classes in one inheritance graph (the class plus all its ancestors).
pub const MAX_BASES: usize = 24;

/// A base table under construction.
///
/// Generated code builds a class's table by taking its base's table, shifting the offsets by
/// where that base sits, and pushing its own entry. That recursion is what lets a class inherit
/// entries for ancestors it was never told about: `#[obj::class(extends = Mid)]` names only `Mid`,
/// yet the resulting table also describes `Mid`'s own ancestors — each entry carrying a vtable
/// specialised to the *derived* class, so a polymorphic cast to a distant ancestor still reaches
/// the most-derived override.
///
/// The capacity is fixed at [`MAX_BASES`] so that array lengths never depend on a generic
/// parameter, which would require the unstable `generic_const_exprs` feature.
#[derive(Clone, Copy, Debug)]
pub struct BaseTable {
    /// Entries, of which the first `len` are live.
    pub entries: [BaseEntry; MAX_BASES],
    /// Number of live entries.
    pub len: usize,
}

impl BaseTable {
    /// An empty table.
    pub const EMPTY: BaseTable = BaseTable {
        entries: [BaseEntry::EMPTY; MAX_BASES],
        len: 0,
    };

    /// Appends an entry.
    ///
    /// # Panics
    ///
    /// At compile time, if the hierarchy exceeds [`MAX_BASES`] classes.
    #[must_use]
    pub const fn push(mut self, entry: BaseEntry) -> Self {
        assert!(
            self.len < MAX_BASES,
            "obj: inheritance graph exceeds MAX_BASES classes",
        );
        self.entries[self.len] = entry;
        self.len += 1;
        self
    }

    /// Shifts every entry's offset by where this subobject sits inside the derived class.
    #[must_use]
    pub const fn offset_by(mut self, delta: usize) -> Self {
        let mut i = 0;
        while i < self.len {
            self.entries[i].data_offset += delta;
            i += 1;
        }
        self
    }

    /// Copies an existing table, dropping every vtable.
    ///
    /// Used for abstract classes, which implement no interface and so have no vtables to record.
    #[must_use]
    pub const fn from_slice_without_vtables(src: &[BaseEntry]) -> Self {
        let mut out = Self::EMPTY;
        let mut i = 0;
        while i < src.len() {
            out = out.push(BaseEntry {
                id: src[i].id,
                data_offset: src[i].data_offset,
                dyn_vtable: None,
            });
            i += 1;
        }
        out
    }

    /// The live entries.
    #[must_use]
    pub const fn as_slice(&self) -> &[BaseEntry] {
        self.entries.split_at(self.len).0
    }
}

impl PartialEq for ClassMeta {
    fn eq(&self, other: &Self) -> bool {
        self.class_id() == other.class_id()
    }
}

impl Eq for ClassMeta {}

impl fmt::Display for ClassMeta {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name)
    }
}
